mapper.select:
select * from dm_device_attribute


        and  dm_device_attribute.name LIKE CONCAT(#{criteria.name},'%')


        and  dm_device_attribute.device_id = #{criteria.deviceId}


        and  dm_device_attribute.device_name LIKE CONCAT(#{criteria.deviceName},'%')


        and  dm_device_attribute.type = #{criteria.type}


        and  dm_device_attribute.status = #{criteria.status}


order by id DESC

mapper.update:
UPDATE dm_device_attribute SET
name=#{name}, device_id=#{deviceId}, device_name=#{deviceName}, control_type=#{controlType},
type=#{type}, address=#{address}, status=#{status}, data=#{data}, plc_data=#{plcData},
temp1=#{temp1}, temp2=#{temp2}
WHERE id=#{id}

UPDATE dm_device_attribute
SET plc_data = #{plcData}
WHERE address = #{address}

choose.when:
UPDATE dm_device_attribute AS t SET plc_data = v.plc_data FROM (VALUES
(CAST(#{item.address} AS VARCHAR), CAST(#{item.plcData} AS VARCHAR))
) AS v(address, plc_data) WHERE t.address = v.address
